'use client';
// Motion Model Comparison (Production page): the same Leo-and-Ben scene generated by each hosted video model on fal.ai.
// Reads /api/motion/comparison (status, estimates, budget; never the API key) and starts runs with
// POST /api/motion/compare {confirm: true}. Paid generation starts only when the owner clicks Run.
import {useState} from 'react';
import {api} from '@/lib/api';
import {useAction, useApi} from '@/lib/hooks';
import {ErrorBox} from '@/components/ui';

const usd = (x: number | null | undefined) => (x === null || x === undefined ? '—' : `$${x.toFixed(2)}`);
const TONE: Record<string, string> = {succeeded: 'good', failed: 'bad', running: 'busy', queued: 'warn', cancelled: ''};

export function MotionComparison() {
  const {data, error, reload} = useApi<any>('/motion/comparison', 4000);
  const {busy, error: actError, run} = useAction(reload);
  const [confirming, setConfirming] = useState(false);
  const [scenario, setScenario] = useState('actions');
  if (!data) return <div className="card"><h2>Motion Model Comparison</h2><ErrorBox error={error} /></div>;
  const p = (data.plans || {})[scenario] || data.plan, left = data.budget_usd - data.spent_usd;
  const rounds = Object.keys(data.scenarios || {talk: {}});
  const reason = !data.key_configured ? 'Save the fal.ai API key in Settings › Credentials first.'
    : data.running ? 'A comparison is running.'
    : !p.fits_budget ? `The estimate (${usd(p.estimated_total_usd)}) exceeds the remaining budget (${usd(left)}).` : '';
  const counts = data.clips.reduce((a: any, c: any) => ({...a, [c.status]: (a[c.status] || 0) + 1}), {});
  const actual = data.clips.reduce((a: number, c: any) => a + (c.actual_usd || 0), 0);
  return (
    <div className="card stack" id="motion-comparison">
      <h2>Motion Model Comparison</h2>
      <p className="muted small">The same 5-second Leo-and-Ben scene, started from their approved artwork, generated by each hosted video model on fal.ai (2 attempts each). Clips appear here and in the Video Library under “Model comparison: Leo &amp; Ben”.</p>
      <ErrorBox error={error || actError} />
      <div className="table-wrap"><table>
        <thead><tr><th>Model</th><th>Licence</th><th>Price</th><th>Est. per clip</th><th>Clips per round</th></tr></thead>
        <tbody>{Object.entries(data.models).map(([k, m]: [string, any]) => (
          <tr key={k}><td><strong>{m.label}</strong></td><td className="small">{m.licence}</td><td className="small">{m.price}</td>
            <td>{usd(m.estimated_usd)}</td><td>2</td></tr>))}</tbody></table></div>
      <div className="stack small">
        <label htmlFor="cmp-round">Round to run</label>
        <select id="cmp-round" value={scenario} onChange={e => { setScenario(e.target.value); setConfirming(false); }}>
          {rounds.map(k => <option key={k} value={k}>{data.scenarios[k].label}</option>)}</select>
        {data.scenarios?.[scenario]?.prompt && <details><summary>Prompt (identical for every model; same 5-second length)</summary><p>{data.scenarios[scenario].prompt}</p></details>}
      </div>
      <div className="row" style={{flexWrap: 'wrap', gap: 16}}>
        <span>Estimated total <strong>{usd(p.estimated_total_usd)}</strong></span>
        <span>Hard spending cap <strong>{usd(data.budget_usd)}</strong></span>
        <span>Spent so far <strong>{usd(data.spent_usd)}</strong></span>
        <span>Status <strong>{data.running ? 'running' : data.clips.length ? 'finished' : 'not started'}</strong>
          {data.clips.length > 0 && <span className="muted small"> ({Object.entries(counts).map(([s, n]) => `${n} ${s}`).join(', ')})</span>}</span>
        <span className={`badge ${data.key_configured ? 'good' : 'bad'}`}>{data.key_configured ? 'fal.ai key saved' : 'fal.ai key missing'}</span>
      </div>
      {!confirming ? (
        <div className="row"><button className="btn primary" disabled={!!busy || !!reason} onClick={() => setConfirming(true)}>Run comparison</button>
          {reason && <span className="muted small">{reason}</span>}</div>
      ) : (
        <div className="row" style={{flexWrap: 'wrap'}}>
          <span>Start 6 paid generations ({data.scenarios?.[scenario]?.label}), estimated <strong>{usd(p.estimated_total_usd)}</strong>?</span>
          <button className="btn primary" disabled={!!busy} onClick={() => run('run', async () => { await api('/motion/compare', {method: 'POST', body: {confirm: true, scenario}}); setConfirming(false); })}>Yes, run ({usd(p.estimated_total_usd)})</button>
          <button className="btn" disabled={!!busy} onClick={() => setConfirming(false)}>Cancel</button>
        </div>)}
      {data.setup && data.setup.status === 'failed' && <div className="small" style={{color: 'var(--bad)'}}>Preparing the first frame failed: {data.setup.error}</div>}
      {data.first_frame_url && <div className="row" style={{alignItems: 'flex-start', gap: 12}}>
        <div className="stack small"><span className="muted">First frame (approved artwork)</span><img src={data.first_frame_url} alt="first frame" style={{width: 120, borderRadius: 6}} /></div></div>}
      {data.clips.length > 0 && <div className="table-wrap"><table>
        <thead><tr><th>Clip</th><th>Status</th><th>Progress</th><th>Cost (est. / actual)</th><th>Output</th></tr></thead>
        <tbody>{[...data.clips].sort((a: any, b: any) => (a.scenario || '').localeCompare(b.scenario || '') || a.model.localeCompare(b.model) || a.attempt - b.attempt).map((c: any) => (
          <tr key={c.job_id}>
            <td><span className="muted small">{data.scenarios?.[c.scenario]?.label || c.scenario}</span><div>{data.models[c.model]?.label || c.model}, attempt {c.attempt}</div><div className="muted small">job #{c.job_id}</div></td>
            <td><span className={`badge ${TONE[c.status] || ''}`}>{c.status}</span></td>
            <td className="small">{c.status === 'running' ? `${c.progress.status || 'starting'}${c.progress.queue_position != null ? ` (queue ${c.progress.queue_position})` : ''} · ${c.progress.elapsed ?? 0} s`
              : c.status === 'succeeded' ? `${c.seconds} s · ${c.width}×${c.height}` : c.error ? <span style={{color: 'var(--bad)'}}>{c.error}</span> : ''}</td>
            <td className="small">{usd(c.estimated_usd)} / {usd(c.actual_usd)}</td>
            <td>{c.url ? <><video controls src={c.url} style={{width: 140, borderRadius: 6}} /><div><a href={c.url} target="_blank" rel="noreferrer">open</a></div></> : '—'}</td>
          </tr>))}</tbody></table></div>}
      {data.clips.length > 0 && <div className="small">Actual cost of finished clips: <strong>{usd(actual)}</strong></div>}
    </div>);
}
